"Bubble Blower" 
@cartocopia 2025-02-15

Not sure how universal this is, but my spawn sure loved playing with bubbles when they were children...

Click and hold to blow larger bubbles, or click and shake madly to make lots of smaller bubbles.

The bubbles gently drift away...Bigger ones pop faster

For the "Children's Games" 🪀 #WCCChallenge ..... Check out the Birb's Nest Discord https://discord.gg/S8c7qcjw2b
*/

let bubbles = [];
let growingBubble = null;
let lastMousePos;
let thisMousePos;
let wind;
let blower;

let mySound;

let bubbleShader;
let bubbleTexture;

function preload() {
	mySound = loadSound('https://openprocessing.org/sketch/2625075/files/pop.mp3');
	bubbleShader = loadShader('https://openprocessing.org/sketch/2625075/files/shader.vert', 'shader.frag');
}

function setup() {
	createCanvas(windowWidth, windowWidth*.75, WEBGL);
	lastMousePos = createVector(0, 0);
	thisMousePos = createVector(0, 0);
	noCursor();
	noStroke();
	mySound.playMode('sustain');
	blower = new Wand();
}

function draw() {
	background("skyblue");

	wind = map(noise(0.0005 * millis()), 0, 1, -2, 2); // global wind to move the bubble around.
	lastMousePos = thisMousePos.copy();
	thisMousePos = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

	// Update and draw all bubbles
	for (let i = bubbles.length - 1; i >= 0; i--) {
		bubbles[i].update();
		bubbles[i].display();

		// Remove popped bubbles
		if (bubbles[i].popped) {
			bubbles.splice(i, 1);
		}
	}

	// Growing bubble
	if (growingBubble) {
		growingBubble.grow();
		growingBubble.display();
		if (thisMousePos.dist(lastMousePos) > growingBubble.size / 2) { //moving fast, release and create a new one
			growingBubble.release();
			bubbles.push(growingBubble);
			mousePressed();
		}
	}

	// Draw the bubble blower wand
	blower.update();
	blower.display();

}

class Wand {
	constructor() {
		this.pos = createVector(width / 2, height / 2);
		this.angle = PI / 4;
	}

	update() {
		this.angle = (this.pos.x - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) / 200 - map(this.pos.y, 0, height, 0, PI / 2);
		this.pos.lerp(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))), 0.5);
	}

	display() {
		push();
		translate(this.pos.x - width / 2, this.pos.y - height / 2, 1);
		stroke("rgb(213,24,24)");
		noFill();
		strokeWeight(6);
		circle(0, 0, 50)
		rotate(this.angle);
		line(0, 25, 0, 200);
		strokeWeight(1);
		for (let i = 0; i < 36; i++) {
			rotate(TAU / 36);
			line(20, 0, 25, 0);
		}
		pop();
	}
}

// Bubble class
class Bubble {
	constructor(x, y, size = random(30, 60)) {
		this.x = x;
		this.y = y;
		this.size = size;
		this.growing = true; // start off growing
		this.speed = random(0.1, 0.5);
		this.drift = 0;
		this.lifetime = millis();
		this.popping = false;
		this.popped = false;
		this.wobble = random(100, 500);
		this.decay = 1;
		this.hue = random(360);
		this.timeoffset = random(1000);
	}

	grow() {
		if (this.growing) {
			this.x = this.x + 0.2 * (thisMousePos.x - this.x); // draging around the bubble
			this.y = this.y + 0.2 * (thisMousePos.y - this.y);
			this.size += map(this.size, 0, width / 2, 20, 0, true); // the bigger the slower we grow
		}
	}

	release() {
		this.growing = false;
		this.drift = constrain((thisMousePos.x - lastMousePos.x) / 10, -2, 2);
		this.lifetime = millis() + random(3000000, 6000000) / this.size
	}

	update() {
		if (!this.growing) {
			this.size *= 0.999;
			this.y -= this.speed;
			this.x += this.drift + wind;
			this.drift *= 0.995;

			// Check if the bubble should pop
			if (!this.popping && millis() >= this.lifetime) {
				mySound.rate(map(this.size, 30, width / 4, 1.2, 0.5, true) * random(0.95, 1.05));
				mySound.amp(map(this.size, 10, width / 4, 0, 0.8, true));
				mySound.play();
				this.popping = true;
			}

			// Handle popping animation
			if (this.popping) {
				this.decay -= 0.2;
				if (this.decay <= 0) {
					this.popped = true; // Remove bubble when too small
				}
			}
		}
	}

	display() {
		push();
		colorMode(HSL);
		translate(this.x - width / 2, this.y - height / 2);
		scale(1 + 0.05 * cos(millis() / this.wobble), 1 + 0.05 * sin(millis() / this.wobble), 1)

		if (!(this.popped || this.popping)) {
			//stroke(color(this.hue, 100, 98, 0.71))
			noStroke();
			fill(color(this.hue, 100, 50, 0.05))
			strokeWeight(2);
			ellipse(0, 0, this.size, this.size, 50);

			blendMode(SCREEN);
			bubbleShader.setUniform('u_time', this.timeoffset + millis() * 0.001); // Pass the time in seconds
			shader(bubbleShader);
			ellipse(0, 0, this.size, this.size, 50);
		}
		if (this.popping) {
			stroke(color(this.hue, 100, 98, 0.71))
			noFill();
			strokeWeight(2);
			arc(0, 0, this.size, this.size, map(this.decay, 1, 0.0001, 0, PI, true) + radians(this.hue), map(this.decay, 1, 0.0001, TAU, PI, true) + radians(this.hue), OPEN);
			strokeWeight(1);
			for (let i = 0; i < 0.5 * this.size * this.decay; i++) {
				let offset = p5.Vector.random2D().mult(0.52 * this.size * sqrt(random(1)));
				circle(offset.x, offset.y, 2);
			}
		}
		pop();
	}
}

// Start growing a bubble
function mousePressed() {
	growingBubble = new Bubble(thisMousePos.x, thisMousePos.y);
}

// Stop growing and let the bubble float
function mouseReleased() {
	if (growingBubble) {
		growingBubble.release();
		bubbles.push(growingBubble);
		growingBubble = null;
	}
}

function keyPressed(){
	save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

// === Tab: shader.frag ===
precision mediump float;

uniform float u_time; // Time passed (for animation)
varying vec2 vTexCoord; // Texture coordinates

// Simple hash function for generating pseudo-random values from coordinates
float hash(vec2 p) {
	return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

// Simple Perlin-like noise function
float perlinNoise(vec2 p) {
	vec2 i = floor(p);
	vec2 f = fract(p);
	f = f * f * (3.0 - 2.0 * f); // Fade function to smooth the transition

	float a = hash(i);
	float b = hash(i + vec2(1.0, 0.0));
	float c = hash(i + vec2(0.0, 1.0));
	float d = hash(i + vec2(1.0, 1.0));

	float x1 = mix(a, b, f.x);
	float x2 = mix(c, d, f.x);
	return mix(x1, x2, f.y);
}

// Rainbow color generator based on Perlin noise value
vec3 getRainbowColor(float t) {
	return vec3(0.5 + 0.5 * sin(t + 0.0), 0.5 + 0.5 * sin(t + 2.0), 0.5 + 0.5 * sin(t + 4.0));
}

// Function to generate noise for transparency
float getNoiseTransparency(vec2 uv) {
	return perlinNoise(uv * 5.0 + u_time * 1.5); // Noise-based transparency
}

void main() {
	// Get the texture coordinates
	vec2 uv = vTexCoord;

	// Apply the Perlin noise pattern for color
	float n = perlinNoise(uv * 1.2 + u_time * 1.0); // Adjust noise scale and speed with u_time

	// Use the Perlin noise value to create a rainbow color
	vec3 color = getRainbowColor(n * 6.28); // Use 2 * PI for a smooth rainbow transition

	// Get transparency value from noise
	float transparency = getNoiseTransparency(uv); // Get the noise-based transparency

	// Binary threshold: If the transparency value is greater than 0.5, make the pixel opaque, else transparent
	float alpha = transparency > 0.5 ? 0.05 : 0.0; // Fully opaque or fully transparent

	// Apply the transparency to the final color
	gl_FragColor = vec4(color, alpha); // Set the final color with noise-based binary transparency
}

// === Tab: shader.vert ===
// Get the position attribute of the geometry
attribute vec3 aPosition;

// Get the texture coordinate attribute from the geometry
attribute vec2 aTexCoord;

// The projection matrix used to convert 3D space to 2D screen space
uniform mat4 uProjectionMatrix;
uniform mat4 uModelViewMatrix;

// Pass texture coordinates to the fragment shader
varying vec2 vTexCoord;

void main() {
	// Transform the vertex position using the projection and model-view matrices
	gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
	vTexCoord = aTexCoord;
}

